-- V20: Batch 3 — gold-standard content for 10 high-priority DSA problems.\n-- Gold-standard content; all problems remain in CONTENT_REVIEW until technical validation.\n\n-- 1 Rotate Array\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='rotate-array'),1,$$Identify the core arrays signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='rotate-array'),2,$$Reverse the whole array, then reverse the first k elements and the remaining elements. The three reversals create exactly the desired cyclic shift.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='rotate-array'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='rotate-array'),$$Rotate the array to the right by k positions.$$,$$Keywords: Rotate Array; ask what structure can be reused instead of recomputed. Look for the arrays pattern and the strongest input constraint.$$,$$Use when elements must be rearranged in-place by a fixed cyclic offset.$$,$$Do not use when relative order must remain unchanged or extra output is explicitly required.$$,$$Reverse the whole array, then reverse the first k elements and the remaining elements. The three reversals create exactly the desired cyclic shift.$$,$$Reverse the whole array, then reverse the first k elements and the remaining elements. The three reversals create exactly the desired cyclic shift.$$,$$Normalize k with k % n and use three reversals.$$,$$Brute force moves one element at a time for k rotations, taking O(nk).$$,'O(nk)','O(1)',$$Normalize k with k % n and use three reversals.$$,'O(n)','O(1)',$$reverse whole array; reverse [0,k-1]; reverse [k,n-1]$$,$$Three reversals move each element exactly to its rotated position while preserving order within each block.$$,$$After each reversal, the reversed segment contains exactly the elements intended for that segment of the final rotation.$$,$$Forget k %= n; mishandle k=0; use k greater than n; reverse the wrong ranges.$$,$$Support left rotation by using n-k as the right-rotation amount. For immutable data, build a new array.$$,$$public void rotate(int[] nums, int k) { int n=nums.length; k%=n; reverse(nums,0,n-1); reverse(nums,0,k-1); reverse(nums,k,n-1); }
private void reverse(int[] a,int l,int r){ while(l<r){ int t=a[l];a[l++]=a[r];a[r--]=t; } }$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='rotate-array'),$$Why does k modulo n preserve the result?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='rotate-array'),$$How would you rotate left?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='rotate-array'),$$Can you do this with a temporary array?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='rotate-array'),$$How would you handle an immutable sequence?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='rotate-array'),$$Can the operation be performed on a distributed array?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='rotate-array'),$$7
