100$$,$$[5]$$,true,3);\n\n-- 2 Move Zeroes\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='move-zeroes'),1,$$Identify the core arrays signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='move-zeroes'),2,$$Scan once, copy each non-zero value forward, then fill the remaining positions with zeroes.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='move-zeroes'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='move-zeroes'),$$Move all zero values to the end while preserving the relative order of non-zero values.$$,$$Keywords: Move Zeroes; ask what structure can be reused instead of recomputed. Look for the arrays pattern and the strongest input constraint.$$,$$Look for stable compaction: keep a write position for the next non-zero value.$$,$$Do not use when the relative order of non-zero elements is irrelevant and a different partitioning strategy is acceptable.$$,$$Scan once, copy each non-zero value forward, then fill the remaining positions with zeroes.$$,$$Scan once, copy each non-zero value forward, then fill the remaining positions with zeroes.$$,$$Use a write pointer and one linear pass, followed by zero fill.$$,$$Repeatedly swapping each zero with the next non-zero can degrade to O(n squared).$$,'O(n^2)','O(1)',$$Use a write pointer and one linear pass, followed by zero fill.$$,'O(n)','O(1)',$$write=0; for each x: if x != 0 place x at write and increment write; fill write..n-1 with zero$$,$$Every non-zero processed is placed in the earliest still-unfilled stable position, so the prefix is always the correct compacted prefix.$$,$$All indices before write contain the non-zero values seen so far in their original order.$$,$$Using swaps that disturb order; writing past the array; forgetting to fill trailing positions.$$,$$Generalize to stable partitioning by an arbitrary predicate. For huge arrays, the same compaction idea can be chunked with prefix counts.$$,$$public void moveZeroes(int[] nums) { int w=0; for(int x:nums) if(x!=0) nums[w++]=x; while(w<nums.length) nums[w++]=0; }$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='move-zeroes'),$$Can you preserve order without a second fill pass?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='move-zeroes'),$$What if zeros are represented by null?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='move-zeroes'),$$How would you stable-partition negative and non-negative values?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='move-zeroes'),$$What is the write amplification of this solution?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='move-zeroes'),$$How could chunks be compacted in parallel?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='move-zeroes'),$$5
