1 2 3 4$$,$$[1,2,3,4]$$,true,3);\n\n-- 3 Majority Element\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='majority-element'),1,$$Identify the core arrays signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='majority-element'),2,$$Pair different values and cancel them conceptually. A true majority has more copies than all other values combined, so it cannot be completely cancelled.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='majority-element'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='majority-element'),$$Find the value occurring more than n/2 times.$$,$$Keywords: Majority Element; ask what structure can be reused instead of recomputed. Look for the arrays pattern and the strongest input constraint.$$,$$An element with strict majority can survive pairwise cancellation.$$,$$Do not use Boyer-Moore without a verification pass when the input contract does not guarantee a majority.$$,$$Pair different values and cancel them conceptually. A true majority has more copies than all other values combined, so it cannot be completely cancelled.$$,$$Pair different values and cancel them conceptually. A true majority has more copies than all other values combined, so it cannot be completely cancelled.$$,$$Use Boyer-Moore voting with one candidate and one counter.$$,$$Counting with a HashMap takes O(n) time and O(n) space.$$,'O(n)','O(n)',$$Use Boyer-Moore voting with one candidate and one counter.$$,'O(n)','O(1)',$$candidate=none; count=0; for x: if count==0 candidate=x; count += (x==candidate ? 1 : -1); return candidate$$,$$The majority contributes more votes than every other value combined, so cancellation leaves it as the final candidate.$$,$$After each step, count represents the unmatched vote balance for candidate.$$,$$Returning an unverified candidate when no majority is guaranteed; integer/count initialization errors.$$,$$Add a verification pass for untrusted input. Weighted votes can be handled with a generalized balance only when the contract supports it.$$,$$public int majorityElement(int[] nums) { int c=0,candidate=0; for(int x:nums){ if(c==0) candidate=x; c += (x==candidate)?1:-1; } return candidate; }$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='majority-element'),$$Why does cancellation preserve the majority?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='majority-element'),$$How do you verify the candidate?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='majority-element'),$$What changes if the threshold is n/3?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='majority-element'),$$Can this work as a stream?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='majority-element'),$$What assumptions are required for a distributed implementation?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='majority-element'),$$7
