1 2 2 2 3$$,$$2$$,true,3);\n\n-- 4 Sort Colors\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='sort-colors'),1,$$Identify the core arrays signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='sort-colors'),2,$$Maintain regions for 0, unknown, and 2. Process the unknown region and place 0s left and 2s right.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='sort-colors'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='sort-colors'),$$Sort an array containing only 0, 1 and 2 in one pass.$$,$$Keywords: Sort Colors; ask what structure can be reused instead of recomputed. Look for the arrays pattern and the strongest input constraint.$$,$$Three known values suggest a three-way partition.$$,$$Do not use Dutch National Flag when the value domain is not fixed to three categories.$$,$$Maintain regions for 0, unknown, and 2. Process the unknown region and place 0s left and 2s right.$$,$$Maintain regions for 0, unknown, and 2. Process the unknown region and place 0s left and 2s right.$$,$$Use Dutch National Flag partitioning.$$,$$Comparison sorting costs O(n log n).$$,'O(n log n)','O(log n) stack or implementation dependent',$$Use Dutch National Flag partitioning.$$,'O(n)','O(1)',$$low=0; mid=0; high=n-1; while mid<=high: 0 swap low/mid and advance; 1 advance; 2 swap mid/high without advancing mid$$,$$Each operation permanently classifies at least one boundary element, so the unknown region shrinks.$$,$$Indices before low are 0, after high are 2, and [low,high] contains only unknown values.$$,$$Advancing mid after swapping with high; incorrect boundaries; unnecessary sort.$$,$$Generalize to k categories using counting when k is small, or multiway partitioning when in-place constraints dominate.$$,$$public void sortColors(int[] a){ int l=0,m=0,h=a.length-1; while(m<=h){ if(a[m]==0){swap(a,l++,m++);} else if(a[m]==2){swap(a,m,h--);} else m++; } }
private void swap(int[]a,int i,int j){int t=a[i];a[i]=a[j];a[j]=t;}$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='sort-colors'),$$Why must mid not advance after swapping a 2?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='sort-colors'),$$How would you handle four colors?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='sort-colors'),$$What is the invariant for the unknown region?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='sort-colors'),$$Can counting sort be simpler here?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='sort-colors'),$$How would you parallelize the partition?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='sort-colors'),$$6
