2 2 1 0 1$$,$$[0,1,1,2,2]$$,true,3);\n\n-- 5 Subarray Sum Equals K\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='subarray-sum-equals-k'),1,$$Identify the core arrays signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='subarray-sum-equals-k'),2,$$At prefix sum s, an earlier prefix s-k forms a valid subarray ending here. Store prefix frequencies in a map.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='subarray-sum-equals-k'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='subarray-sum-equals-k'),$$Count contiguous subarrays whose sum equals k.$$,$$Keywords: Subarray Sum Equals K; ask what structure can be reused instead of recomputed. Look for the arrays pattern and the strongest input constraint.$$,$$Prefix sums turn a subarray sum into the difference of two prefix sums.$$,$$Do not use a plain sliding window when negative numbers are allowed.$$,$$At prefix sum s, an earlier prefix s-k forms a valid subarray ending here. Store prefix frequencies in a map.$$,$$At prefix sum s, an earlier prefix s-k forms a valid subarray ending here. Store prefix frequencies in a map.$$,$$Use prefix-sum frequency hashing.$$,$$Checking every start/end pair takes O(n squared).$$,'O(n^2)','O(1)',$$Use prefix-sum frequency hashing.$$,'O(n)','O(n)',$$map[0]=1; sum=0; for x: sum+=x; answer += map[sum-k]; map[sum]++$$,$$Each prior prefix with value sum-k identifies one unique subarray ending at the current index.$$,$$Before processing index i, the map contains frequencies of all prefix sums ending before i.$$,$$Adding the current prefix before querying; using sliding window with negatives; forgetting map[0]=1.$$,$$For very large sums use long. Distributed prefix scans need boundary prefix offsets to combine partition counts correctly.$$,$$public int subarraySum(int[] nums,int k){ Map<Integer,Integer> m=new HashMap<>(); m.put(0,1); int s=0,ans=0; for(int x:nums){s+=x; ans+=m.getOrDefault(s-k,0); m.put(s,m.getOrDefault(s,0)+1);} return ans; }$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='subarray-sum-equals-k'),$$Why does sliding window fail with negative numbers?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='subarray-sum-equals-k'),$$Why is map[0] initialized to one?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='subarray-sum-equals-k'),$$Can you return the actual ranges?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='subarray-sum-equals-k'),$$What changes if all numbers are positive?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='subarray-sum-equals-k'),$$How would you process this in chunks?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='subarray-sum-equals-k'),$$5
