7$$,$$1$$,true,3);\n\n-- 6 Longest Consecutive Sequence\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='longest-consecutive-sequence'),1,$$Identify the core hashing signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='longest-consecutive-sequence'),2,$$Only start counting from x when x-1 is absent. Then walk x+1, x+2, and so on.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='longest-consecutive-sequence'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='longest-consecutive-sequence'),$$Find the longest run of consecutive integer values in an unsorted array.$$,$$Keywords: Longest Consecutive Sequence; ask what structure can be reused instead of recomputed. Look for the hashing pattern and the strongest input constraint.$$,$$Hash membership allows sequence starts to be detected without sorting.$$,$$Do not use this approach when you must preserve duplicate occurrences or need sorted output.$$,$$Only start counting from x when x-1 is absent. Then walk x+1, x+2, and so on.$$,$$Only start counting from x when x-1 is absent. Then walk x+1, x+2, and so on.$$,$$Use a HashSet and expand only from sequence starts.$$,$$Sorting first costs O(n log n).$$,'O(n log n)','O(1) auxiliary excluding sorting implementation',$$Use a HashSet and expand only from sequence starts.$$,'O(n) expected','O(n)',$$put all values in a set; for each x with no x-1, increment y while y exists; keep max$$,$$Each number is extended through only from a valid sequence start, so total membership checks are linear in expectation.$$,$$For every processed start, the counted sequence begins at a value whose predecessor is absent.$$,$$Starting a scan from every value; forgetting duplicates; claiming deterministic O(n) for a hash table.$$,$$Use a balanced tree for deterministic O(n log n), or external hashing for very large datasets.$$,$$public int longestConsecutive(int[] nums){ Set<Integer>s=new HashSet<>(); for(int x:nums)s.add(x); int best=0; for(int x:s) if(!s.contains(x-1)){int y=x,len=1; while(s.contains(y+1)){y++;len++;} best=Math.max(best,len);} return best; }$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='longest-consecutive-sequence'),$$Why is each number processed only a constant number of times amortized?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='longest-consecutive-sequence'),$$What happens with duplicates?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='longest-consecutive-sequence'),$$What is the deterministic alternative?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='longest-consecutive-sequence'),$$How would you handle integer overflow at MIN_VALUE?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='longest-consecutive-sequence'),$$How could this be implemented across partitions?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='longest-consecutive-sequence'),$$6
