5 5 6$$,$$2$$,true,3);\n\n-- 7 Top K Frequent Elements\nINSERT INTO hints(problem_id,level,content,label) VALUES\n((SELECT id FROM problems WHERE slug='top-k-frequent-elements'),1,$$Identify the core hashing signal in the problem statement and focus on the constraint that makes a linear or near-linear approach possible.$$,'Concept'),\n((SELECT id FROM problems WHERE slug='top-k-frequent-elements'),2,$$Build frequencies. A min-heap of size k keeps the best k candidates seen so far.$$,'Direction'),\n((SELECT id FROM problems WHERE slug='top-k-frequent-elements'),3,$$Trace the invariant while processing the input; the implementation should preserve it after every iteration.$$,'Algorithm')\nON CONFLICT(problem_id,level) DO UPDATE SET content=EXCLUDED.content,label=EXCLUDED.label;\n\nINSERT INTO problem_content(problem_id,recognition_note,pattern_recognition_clues,when_to_use,when_not_to_use,intuition,guided_reasoning,solution,brute_force,brute_time,brute_space,optimal_approach,optimal_time,optimal_space,pseudocode,why_this_works,invariant,common_mistakes,senior_variations,java_solution,content_status) VALUES\n((SELECT id FROM problems WHERE slug='top-k-frequent-elements'),$$Return the k values with the highest frequencies.$$,$$Keywords: Top K Frequent Elements; ask what structure can be reused instead of recomputed. Look for the hashing pattern and the strongest input constraint.$$,$$Count first, then select the k highest counts with a heap or buckets.$$,$$Do not use a heap when the output contract and frequency bounds make bucket selection simpler.$$,$$Build frequencies. A min-heap of size k keeps the best k candidates seen so far.$$,$$Build frequencies. A min-heap of size k keeps the best k candidates seen so far.$$,$$Use a size-k min-heap.$$,$$Sorting all distinct values by frequency costs O(m log m), where m is the number of distinct values.$$,'O(m log m)','O(m)',$$Use a size-k min-heap.$$,'O(n + m log k)','O(m + k)',$$count frequencies; push entries into min-heap; if size>k pop; extract keys$$,$$The heap root is always the weakest member among the current top k, so a stronger candidate can replace it.$$,$$After each distinct value, the heap contains the best k values seen so far.$$,$$Using a max-heap and accidentally returning all elements; mishandling ties; ignoring that output order may be unspecified.$$,$$Use bucket sort for O(n) expected work when frequency is bounded by n. Define deterministic tie-breaking if required.$$,$$public int[] topKFrequent(int[] nums,int k){ Map<Integer,Integer> m=new HashMap<>(); for(int x:nums)m.put(x,m.getOrDefault(x,0)+1); PriorityQueue<int[]>q=new PriorityQueue<>((a,b)->Integer.compare(a[1],b[1])); for(var e:m.entrySet()){q.offer(new int[]{e.getKey(),e.getValue()}); if(q.size()>k)q.poll();} int[]r=new int[k]; for(int i=k-1;i>=0;i--)r[i]=q.poll()[0]; return r; }$$,'CONTENT_REVIEW');\n\nINSERT INTO problem_followups(problem_id,question,type,sort_order) VALUES\n((SELECT id FROM problems WHERE slug='top-k-frequent-elements'),$$How would you make tie-breaking deterministic?$$,'FOLLOWUP',1),\n((SELECT id FROM problems WHERE slug='top-k-frequent-elements'),$$When is bucket sort preferable?$$,'FOLLOWUP',2),\n((SELECT id FROM problems WHERE slug='top-k-frequent-elements'),$$How would you return all ties at the kth frequency?$$,'FOLLOWUP',3),\n((SELECT id FROM problems WHERE slug='top-k-frequent-elements'),$$What changes for a streaming input?$$,'SENIOR',4),\n((SELECT id FROM problems WHERE slug='top-k-frequent-elements'),$$How would you distribute counting?$$,'SENIOR',5)\nON CONFLICT DO NOTHING;\n\nINSERT INTO test_cases(id,problem_id,input,expected_output,is_hidden,display_order) VALUES\n(gen_random_uuid(),(SELECT id FROM problems WHERE slug='top-k-frequent-elements'),$$6
